import unittest
from unittest.mock import call, patch

import config
import importers


SHA = 'a' * 40
REFERENCE = {'ref': 'refs/heads/main', 'object': {'sha': SHA}}
PAYLOAD = {'fixture': 'public catalog'}
FETCH = 'importers._fetch_public_catalog_json'


class PublicFeedRoutingTests(unittest.TestCase):
    """Resolve only the configured public branch and immutable repository snapshot."""

    def test_valid_ref_reads_the_immutable_commit_url(self):
        """Use the resolved SHA rather than trusting the stale branch-name Raw cache."""
        pinned = config.UNICLUBS_RAW_REPOSITORY_URL + '/' + SHA
        pinned += config.UNICLUBS_PUBLIC_EXPORT_PATH
        with patch(FETCH, side_effect=[REFERENCE, PAYLOAD]) as fetch:
            self.assertEqual(importers.fetch_public_uniclubs_feed(), PAYLOAD)
        self.assertEqual(fetch.call_args_list,
                         [call(config.UNICLUBS_GITHUB_REF_URL, config.UNICLUBS_MAX_HTML_BYTES),
                          call(pinned, config.UNICLUBS_MAX_EXPORT_BYTES)])

    def test_invalid_refs_cannot_redirect_downloads_outside_the_public_feed(self):
        """Malformed refs and path-like SHA values must select only the configured fallback."""
        invalid = [
            {'ref': 'refs/heads/other', 'object': {'sha': SHA}},
            {'ref': 'refs/heads/main', 'object': {'sha': 'https://other.example/private'}},
            {'ref': 'refs/heads/main', 'object': {'sha': 'a' * 39 + '/'}},
            {'ref': 'refs/heads/main', 'object': {'sha': 123}},
            {},
        ]
        for reference in invalid:
            with self.subTest(reference=reference):
                with patch(FETCH, side_effect=[reference, PAYLOAD]) as fetch:
                    self.assertEqual(importers.fetch_public_uniclubs_feed(), PAYLOAD)
                self.assertEqual(fetch.call_args,
                                 call(config.UNICLUBS_PUBLIC_EXPORT_URL,
                                      config.UNICLUBS_MAX_EXPORT_BYTES))

    def test_unavailable_ref_falls_back_without_requiring_credentials(self):
        """A rate-limited or unavailable public API must not prevent a usable raw snapshot."""
        with patch(FETCH, side_effect=[ValueError('API unavailable'), PAYLOAD]) as fetch:
            self.assertEqual(importers.fetch_public_uniclubs_feed(), PAYLOAD)
        self.assertEqual(fetch.call_count, 2)
        self.assertEqual(fetch.call_args.args[0], config.UNICLUBS_PUBLIC_EXPORT_URL)

    def test_failed_pinned_download_tries_the_public_branch_url_once(self):
        """A temporarily unavailable immutable file may use a valid cached branch snapshot."""
        with patch(FETCH, side_effect=[REFERENCE, ValueError('Not ready'), PAYLOAD]) as fetch:
            self.assertEqual(importers.fetch_public_uniclubs_feed(), PAYLOAD)
        self.assertEqual(fetch.call_count, 3)
        self.assertEqual(fetch.call_args.args[0], config.UNICLUBS_PUBLIC_EXPORT_URL)

    def test_failed_fallback_is_not_retried_in_an_unbounded_loop(self):
        """Stop after the single fallback fails so the consumer can retain local data."""
        with patch(FETCH, side_effect=[ValueError('Ref'), ValueError('Feed')]) as fetch:
            with self.assertRaises(ValueError):
                importers.fetch_public_uniclubs_feed()
        self.assertEqual(fetch.call_count, 2)


class PublicFeedTransportTests(unittest.TestCase):
    """Exercise the real JSON transport through isolated mocked HTTP responses."""

    def setUp(self):
        """Replace requests transport without replacing its bounded decoding implementation."""
        replacement = patch('importers.requests.get')
        self.get = replacement.start()
        self.addCleanup(replacement.stop)
        self.response = self.get.return_value.__enter__.return_value
        self.response.status_code = 200
        self.response.iter_content.return_value = [b'{"fixture":"public catalog"}']

    def test_public_transport_uses_verified_tls_and_no_authentication(self):
        """Keep proxy/TLS defaults while explicitly bounding and decoding public JSON."""
        result = importers._fetch_public_catalog_json(config.UNICLUBS_PUBLIC_EXPORT_URL, 100)
        self.assertEqual(result, PAYLOAD)
        options = self.get.call_args.kwargs
        self.assertEqual(options['timeout'], config.HTTP_TIMEOUT_SECONDS)
        self.assertTrue(options['stream'])
        self.assertFalse(options['allow_redirects'])
        self.assertIsNot(options.get('verify'), False)
        self.assertNotIn('auth', options)
        self.assertNotIn('cookies', options)
        self.assertNotIn('Authorization', options['headers'])
        self.get.return_value.__exit__.assert_called_once()

    def test_oversize_and_invalid_json_are_rejected_before_consumption(self):
        """Do not accept partial, damaged or oversized bytes as a public catalog object."""
        for content, limit in ((b'{"large":"value"}', 4), (b'{incomplete', 100),
                               (b'\xff', 100)):
            with self.subTest(content=content):
                self.response.iter_content.return_value = [content]
                with self.assertRaises(ValueError):
                    importers._fetch_public_catalog_json(config.UNICLUBS_PUBLIC_EXPORT_URL,
                                                        limit)

    def test_transport_failure_is_sanitized(self):
        """Raw network diagnostic content must not become the user-facing feed error."""
        self.get.side_effect = importers.requests.Timeout('secret-source-marker')
        with self.assertRaises(ValueError) as caught:
            importers._fetch_public_catalog_json(config.UNICLUBS_PUBLIC_EXPORT_URL, 100)
        self.assertNotIn('secret-source-marker', str(caught.exception))


if __name__ == '__main__':
    unittest.main()
